    val list: List<CountryIndicatorValueEntity> by lazy {
        rawData.lineSequence()
            .filter { it.isNotBlank() }
            .map { line ->
                val p = line.split(",")
                CountryIndicatorValueEntity(
                    isoCode = p[0],
                    indicatorId = p[1],
                    categoryId = p[2],
                    year = p[3].toInt(),
                    value = p[4].toDouble(),
